'declare',
'    l_blob          blob;',
'    l_mime_type     varchar2(255);',
'    l_filename      varchar2(255);',
'begin',
'    if :P1_FILE is not null then',
'        select blob_content, mime_type, filename',
'          into l_blob, l_mime_type, l_filename',
'          from apex_application_temp_files',
'         where name = :P1_FILE;',
'    end if;',
'',
'    insert into SM_POSTS (',
'        POST_TEXT,',
'        USER_NAME,',
'        LATITUDE,',
'        LONGITUDE,',
'        CREATED_AT,',
'        IMAGE_FILE,',
'        IMAGE_MIME_TYPE,',
'        IMAGE_FILE_NAME',
'    ) values (',
'        :P1_POST_TEXT,',
'        :APP_USER,',
'        :P1_LAT,',
'        :P1_LON,',
'        sysdate,',
'        l_blob,',
'        l_mime_type,',
'        l_filename',
'    );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Posted!'
,p_internal_uid=>37506104192333372139
